// #db7e39 פעולות מחיקה וביטול — окна подтверждения на /users (משתמשי החברה): «ביטול הזמנה» и «שינוי הרשאה».
// Кейсы: .qa/tests/confirm-dialogs/CD-01, CD-04. План: specs/confirm-dialogs.md (раздел 1).
// ADMIN2 (компания B, .qa/auth/admin2.json). Приглашения — только qa-auto-confirm-…@example.com, в finally все такие
// отменяются (с подтверждением). Смена роли — только у QA Inv14 Member (INV14, компания B; НЕ QA Member 2),
// в finally роль возвращается на «משתמש רגיל». Меняет данные → @data (идёт один, десктоп).
import { test, expect, Page } from '@playwright/test';
import { authState } from '../helpers/tenderflow';
import { CONFIRM_CANCEL, PENDING, cancelAllInvites, invite, openCancelDialog, rowOf, usersHeading } from '../helpers/invites';
import { confirmDialog, dismissAllWays, expectConfirmDialog, trackWrites } from './confirm';

const INVITE_NAME = 'QA-AUTO Confirm';
const QA_INVITES = /qa-auto-confirm-/;
const qaEmail = () => `qa-auto-confirm-${Date.now()}-${Math.floor(Math.random() * 1000)}@example.com`;

const MEMBER = 'QA Inv14 Member';
const ADMIN_ROLE = 'מנהל חשבון';
const USER_ROLE = 'משתמש רגיל';
const ROLE_DIALOG = 'שינוי הרשאה';

const roleCombo = (page: Page) => page.getByRole('combobox', { name: `הרשאה עבור ${MEMBER}` });
const selectedRole = (page: Page) => roleCombo(page).locator('option:checked');

async function openUsers(page: Page) {
  await page.goto('/users');
  await expect(usersHeading(page)).toBeVisible();
  await expect(roleCombo(page)).toBeEnabled();
}

/** Выбрать роль в списке → открыто окно «שינוי הרשאה». */
async function pickRole(page: Page, role: string) {
  await roleCombo(page).selectOption({ label: role });
  const dialog = confirmDialog(page, ROLE_DIALOG);
  await expect(dialog).toBeVisible();
  return dialog;
}

/** Очистка: вернуть QA Inv14 Member роль «משתמש רגיל» (через окно подтверждения) и проверить после F5. */
async function restoreMemberRole(page: Page) {
  await openUsers(page);
  if ((await selectedRole(page).textContent())?.trim() !== USER_ROLE) {
    const dialog = await pickRole(page, USER_ROLE);
    await dialog.getByRole('button', { name: ROLE_DIALOG, exact: true }).click();
    await expect(dialog).toBeHidden();
  }
  await page.reload();
  await expect(roleCombo(page)).toBeEnabled();
  await expect(selectedRole(page)).toHaveText(USER_ROLE);
}

test.use({ storageState: authState('admin2') });

test.describe('חלונות אישור — משתמשי החברה', () => {
  test('ביטול הזמנה: חלון אישור; "חזרה", Escape ולחיצה מחוץ לחלון משאירים את ההזמנה; "ביטול ההזמנה" מסיר אותה #db7e39 @desktop @data', async ({ page }) => {
    // CD-01
    const email = qaEmail();
    try {
      await invite(page, INVITE_NAME, email);
      const writes = trackWrites(page);

      // Окно: текст с именем, «חזרה» / «ביטול ההזמנה», фокус на «חזרה» (комм. программиста 12.11).
      let dialog = await openCancelDialog(page, email);
      await expectConfirmDialog(dialog, `לבטל את ההזמנה של ${INVITE_NAME}?`, CONFIRM_CANCEL);
      await expect(dialog).toContainText('קישור ההצטרפות שנשלח יפסיק לעבוד.');
      await dialog.getByRole('button', { name: 'חזרה', exact: true }).click();
      await expect(dialog).toBeHidden();

      // «חזרה» / Escape / клик вне окна — приглашение на месте, на сервер ничего не ушло.
      await dismissAllWays(page, () => openCancelDialog(page, email), async () => {
        await expect(rowOf(page, email).first()).toContainText(PENDING);
      });
      expect(writes, 'отмена окна не отправляет запросов записи').toEqual([]);
      await page.reload();
      await expect(usersHeading(page)).toBeVisible();
      await expect(rowOf(page, email).first()).toContainText(PENDING);

      // Подтверждение — строки нет, и после F5 тоже (L-20261025-6).
      dialog = await openCancelDialog(page, email);
      await dialog.getByRole('button', { name: CONFIRM_CANCEL, exact: true }).click();
      await expect(dialog).toBeHidden();
      await expect(rowOf(page, email)).toHaveCount(0);
      await page.reload();
      await expect(usersHeading(page)).toBeVisible();
      await expect(page.getByRole('row').filter({ hasText: 'פעיל' }).first()).toBeVisible();
      await expect(rowOf(page, email)).toHaveCount(0);
    } finally {
      await cancelAllInvites(page, QA_INVITES);
    }
    await expect(page.getByRole('row').filter({ hasText: QA_INVITES })).toHaveCount(0);
  });

  test('שינוי הרשאה: חלון אישור; "חזרה" ו-Escape לא משנים את ההרשאה; אישור משנה ונשמר אחרי רענון #db7e39 @desktop @data', async ({ page }) => {
    // CD-04 — только QA Inv14 Member (компания B). Роль возвращается в finally.
    try {
      await openUsers(page);
      await expect(selectedRole(page), 'исходная роль участника').toHaveText(USER_ROLE);
      const writes = trackWrites(page);

      // Окно: «לשנות את ההרשאה של QA Inv14 Member מ«משתמש רגיל» ל«מנהל חשבון»?», «חזרה» / «שינוי הרשאה», фокус на «חזרה».
      let dialog = await pickRole(page, ADMIN_ROLE);
      await expectConfirmDialog(dialog, `לשנות את ההרשאה של ${MEMBER} מ«${USER_ROLE}» ל«${ADMIN_ROLE}»?`, ROLE_DIALOG);

      // «חזרה» — роль не меняется.
      await dialog.getByRole('button', { name: 'חזרה', exact: true }).click();
      await expect(dialog).toBeHidden();
      await expect(selectedRole(page)).toHaveText(USER_ROLE);

      // Escape — роль не меняется.
      dialog = await pickRole(page, ADMIN_ROLE);
      await page.keyboard.press('Escape');
      await expect(dialog).toBeHidden();
      await expect(selectedRole(page)).toHaveText(USER_ROLE);

      expect(writes, 'отмена окна не отправляет запросов записи').toEqual([]);
      await page.reload();
      await expect(roleCombo(page)).toBeEnabled();
      await expect(selectedRole(page)).toHaveText(USER_ROLE);

      // Подтверждение — «מנהל חשבון» сохраняется после F5 (S-02 AC5).
      dialog = await pickRole(page, ADMIN_ROLE);
      await dialog.getByRole('button', { name: ROLE_DIALOG, exact: true }).click();
      await expect(dialog).toBeHidden();
      await expect(selectedRole(page)).toHaveText(ADMIN_ROLE);
      await page.reload();
      await expect(roleCombo(page)).toBeEnabled();
      await expect(selectedRole(page)).toHaveText(ADMIN_ROLE);

      // Обратно — тоже через окно, с обратным текстом.
      dialog = await pickRole(page, USER_ROLE);
      await expectConfirmDialog(dialog, `לשנות את ההרשאה של ${MEMBER} מ«${ADMIN_ROLE}» ל«${USER_ROLE}»?`, ROLE_DIALOG);
      await dialog.getByRole('button', { name: ROLE_DIALOG, exact: true }).click();
      await expect(dialog).toBeHidden();
    } finally {
      await restoreMemberRole(page);
    }
  });
});
